package cn.balltv.portal;
import java.util.*;import java.io.*;import org.json.*;
/** Public anonymous site APIs, never a third-party playlist subscription. */
public final class ExtraSources {
 static final String KQT="看球通",SOMI="So米";
 static boolean handles(String s){return s.equals(KQT)||s.equals(SOMI);}
 static String base(String s){return s.equals(SOMI)?"https://www.smzb138.com":"https://www.kqt600.com";}
 static JSONObject get(String source,String path,boolean cache)throws Exception{JSONObject root=(JSONObject)HttpData.json(HttpData.get((source.equals(SOMI)?"https://aapinew2.smzb666.com":"https://aapi20.xbncs.com")+path+(path.contains("?")?"&":"?")+"channelId=3&platform=1",base(source)+"/",cache).body);if(root.optInt("code")!=200)throw new IOException(root.optString("message","来源接口异常"));return root.getJSONObject("data");}
 static Feeds.Page fetch(String source,String view,int page)throws Exception{JSONObject matches=get(source,"/api/match/hot?date=",true),rooms=get(source,"/api/room/hotAppRoom?size=100",true);return MoreSources.page(parseSite(source,matches,rooms,view),page);}
 public static List<Feeds.Match> parseKqt(JSONObject matches,JSONObject rooms,String view)throws Exception{return parseSite(KQT,matches,rooms,view);}
 public static List<Feeds.Match> parseSite(String source,JSONObject matches,JSONObject rooms,String view)throws Exception{Map<String,JSONObject> events=new LinkedHashMap<String,JSONObject>();JSONArray list=matches.optJSONArray("list");if(list!=null)for(int i=0;i<list.length();i++){JSONObject m=list.getJSONObject(i);events.put(Feeds.str(m,"matchId"),m);}Map<String,JSONArray> grouped=new LinkedHashMap<String,JSONArray>();Map<String,JSONObject> first=new HashMap<String,JSONObject>();JSONArray live=rooms.optJSONArray("list");if(live!=null)for(int i=0;i<live.length();i++){JSONObject room=live.getJSONObject(i);if(!roomAllowed(room))continue;String id=Feeds.str(room,"matchId");if(id.isEmpty())id="room:"+Feeds.str(room,"roomId");if(!grouped.containsKey(id)){grouped.put(id,new JSONArray());first.put(id,room);}grouped.get(id).put(new JSONObject().put("id",Feeds.str(room,"roomId")).put("name",Feeds.str(room,"nickName")));}
  ArrayList<Feeds.Match> result=new ArrayList<Feeds.Match>();Set<String> ids=new LinkedHashSet<String>();ids.addAll(events.keySet());ids.addAll(grouped.keySet());for(String id:ids){JSONObject event=events.get(id),room=first.get(id);if(event==null)event=new JSONObject();if(room==null)room=new JSONObject();Feeds.Match m=MoreSources.match(source,id);m.home=Feeds.str(event,"homeName");m.away=Feeds.str(event,"awayName");m.title=m.home.isEmpty()?Feeds.str(room,"title"):m.home+" vs "+m.away;m.league=Feeds.str(event,"leagueName");if(m.league.isEmpty())m.league=Feeds.str(room,"leagueName","navName");m.sport=Feeds.str(event,"matchType");if(m.sport.isEmpty())m.sport=Feeds.str(room,"matchType");if(m.sport.equals("3"))m.sport="esports";m.time=Feeds.str(event,"matchTime");m.score=Feeds.str(event,"homeScore")+" : "+Feeds.str(event,"awayScore");if(m.score.trim().equals(":"))m.score="";m.cover=Feeds.str(room,"cover");m.room=Feeds.str(room,"roomId");m.status=grouped.containsKey(id)?"live":"upcoming";long at=Events.epoch(m.time);if(at>System.currentTimeMillis()+60000)m.status="upcoming";m.eventState=LiveState.matchCode(m.sport,event.optInt("matchState",-1));if(!m.eventState.isEmpty())m.status=m.eventState;m.raw.put("rooms",grouped.containsKey(id)?grouped.get(id):new JSONArray());MoreSources.pack(m);result.add(m);}return result;}
 public static boolean roomAllowed(JSONObject r){return r.optInt("state")==1&&r.optInt("isForceLogin")==0&&!SourceSafety.promotional(Feeds.str(r,"title")+" "+Feeds.str(r,"nickName"))&&!Feeds.str(r,"title").matches(".*(回放|录播|重播).* ".trim());}
 static ArrayList<Feeds.Line> lines(Feeds.Match m)throws Exception{JSONObject current=get(m.source,"/api/room/hotAppRoom?size=100",false);JSONArray rooms=current.getJSONArray("list");ArrayList<Feeds.Line> out=new ArrayList<Feeds.Line>();for(int i=0;i<rooms.length();i++){JSONObject r=rooms.getJSONObject(i);String id=Feeds.str(r,"matchId");if(id.isEmpty())id="room:"+Feeds.str(r,"roomId");if(!id.equals(m.id)||!roomAllowed(r))continue;Feeds.Line line=new Feeds.Line(Feeds.str(r,"nickName"),Feeds.str(r,"roomId"),"");line.referer=base(m.source)+"/";out.add(line);}return out;}
 static String resolve(Feeds.Match m,Feeds.Line l)throws Exception{JSONObject d=get(m.source,"/api/room/detail?roomId="+l.id,false);if(d.optInt("isForceLogin")!=0)throw new IOException("此线路需要登录，已跳过");if(!roomAllowed(d))throw new IOException("主播已离线或内容不符合筛选条件");String matchId=Feeds.str(d,"matchId");if(!m.id.startsWith("room:")&&!m.id.equals(matchId))throw new IOException("该房间已切换赛事，请刷新");String url=Feeds.str(d,"pullUrl");if(!StreamResolver.direct(url))throw new IOException("当前未提供原生可播放线路");return url;}
}
